  ('SSS3','LVF','LVF-T5','LVF-T5-O2','Keep and interpret farm records for decision making','{WASSCE,NECO}',2),
  ('SSS3','SPV','SPV-T1','SPV-T1-O1','Explain solar energy sources and the photovoltaic effect','{WASSCE,NECO}',1),
  ('SSS3','SPV','SPV-T1','SPV-T1-O2','Identify types of solar cells and modules','{WASSCE,NECO}',2),
  ('SSS3','SPV','SPV-T2','SPV-T2-O1','Describe the function of charge controllers, inverters and batteries','{WASSCE,NECO}',1),
  ('SSS3','SPV','SPV-T2','SPV-T2-O2','Interpret module ratings and system wiring components','{WASSCE,NECO}',2),
  ('SSS3','SPV','SPV-T3','SPV-T3-O1','Select appropriate tools and materials for PV installation','{WASSCE,NECO}',1),
  ('SSS3','SPV','SPV-T3','SPV-T3-O2','Apply safety practices during installation and maintenance','{WASSCE,NECO}',2),
